{
  "workspace": {
    "name": "retail_bi_workspace",
    "region": "cn-hangzhou",
    "engine": "MaxCompute",
    "project": "retail_bi",
    "members": [
      {"user": "张三", "role": "开发"},
      {"user": "李四", "role": "运维"},
      {"user": "王五", "role": "访客"}
    ],
    "tables": ["ods_order", "dwd_order_detail", "ads_dau"]
  }
}

{
  "taskName": "sync_mysql_order_to_odw",
  "type": "offline_sync",
  "source": {
    "datasource": "mysql_orders",
    "table": "orders",
    "incrementField": "update_time",
    "startTime": "2024-01-01 00:00:00"
  },
  "destination": {
    "datasource": "maxcompute_retail_bi",
    "table": "ods_order",
    "writeMode": "append"
  },
  "columnMapping": [
    {"source": "id", "target": "id"},
    {"source": "user_id", "target": "user_id"},
    {"source": "amount", "target": "amount"},
    {"source": "update_time", "target": "update_time"}
  ],
  "schedule": {"cron": "30 1 * * *", "retry": 3}
}

{
  "node": "ads_report",
  "schedule": {
    "cycle": "day",
    "cron": "0 4 * * *",
    "timezone": "Asia/Shanghai"
  },
  "dependsOn": ["dws_user_sum", "dws_goods_sum"],
  "timeout": 60,
  "retry": {"times": 3, "intervalMin": 5},
  "alarm": {"onFail": true, "channels": ["钉钉群"]}
}

{
  "table": "ods_order",
  "rules": [
    {"rule": "行数波动", "thresholdPercent": 20, "compareWith": "昨天"},
    {"rule": "空值率", "column": "order_id", "maxPercent": 0.01},
    {"rule": "唯一性", "column": "order_id", "mustBeUnique": true}
  ],
  "onViolation": {"alarm": true, "blockDownstream": true}
}
